package dev.zomboidmelee.boxing;
/** Cosmetic reach only. Never cancels interaction, attacks, consumes an item, or changes blocks. */
public final class Interact22{
 static boolean candidate(String id){return id.contains("door")||id.contains("trapdoor")||id.contains("chest")||id.contains("barrel")||id.contains("corpse")||id.contains("remains")||id.contains("storage")||id.contains("cabinet")||id.contains("drawer")||id.contains("desk")||id.contains("washing_machine")||id.contains("fridge")||id.contains("furnace");}
 public static void block(Object event){if(R.yes(R.call(event,"isCanceled"))||!"MAIN_HAND".equals(R.call(event,"getHand").toString()))return;Object p=R.call(event,"getEntity");if(!Boxing16.empty(p)||!R.yes(R.call(p,"isAlive"))||R.yes(R.call(p,"isUsingItem")))return;Object block=R.call(R.call(R.call(p,"level"),"getBlockState",R.call(event,"getPos")),"getBlock"),registry=R.get(R.type("net.minecraft.core.registries.BuiltInRegistries"),"BLOCK");if(!candidate(R.call(registry,"getKey",block).toString()))return;show(p);}
 public static void entity(Object event){if(R.yes(R.call(event,"isCanceled"))||!"MAIN_HAND".equals(R.call(event,"getHand").toString()))return;Object p=R.call(event,"getEntity"),v=R.call(event,"getTarget");if(!Boxing16.empty(p)||!R.yes(R.call(p,"isAlive"))||R.yes(R.call(p,"isUsingItem")))return;Object registry=R.get(R.type("net.minecraft.core.registries.BuiltInRegistries"),"ENTITY_TYPE");String id=R.call(registry,"getKey",R.call(v,"getType")).toString();if(id.contains("corpse")||id.contains("remains"))show(p);}
 static void show(Object p){if(R.type("net.minecraft.server.level.ServerPlayer").isInstance(p)&&!R.yes(R.call(R.call(p,"level"),"isClientSide"))){Net20.cue(p,22);return;}if(!R.yes(R.call(R.call(p,"level"),"isClientSide")))return;R.call(R.type("dev.zomboidmelee.boxing.InteractClient22"),"show",p);}
}
